#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7
cd "$(dirname "$0")/.."           # chạy từ gốc repo, dù gọi từ đâu
mkdir -p deploy
ENV_FILE="deploy/s3.env"           # chỉ chứa bucket/region/profile, không chứa secret
S3_PROFILE="kafka-portal"

# Endpoint website theo region (bảng "Amazon S3 website endpoints" trong AWS General Reference)
website_url() {
  case "$1" in
    us-east-1|us-west-1|us-west-2|ap-southeast-1|ap-southeast-2|ap-northeast-1|eu-west-1|sa-east-1|us-gov-west-1)
      echo "http://$2.s3-website-$1.amazonaws.com" ;;
    *) echo "http://$2.s3-website.$1.amazonaws.com" ;;
  esac
}

banner "Kafka Learning Portal lên AWS S3 static website"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Kiểm tra môi trường"
case "$(uname -s)" in
  MINGW*|MSYS*|CYGWIN*) OS_KIND=windows ;;
  Linux) OS_KIND=linux ;;
  *) warn "Chạy wizard trong Git Bash (Windows) hoặc WSL/Linux."; exit 1 ;;
esac
# Bộ cài MSI đặt aws.exe ở đây; terminal mở trước khi cài chưa có trong PATH
[[ "$OS_KIND" == windows && -d "/c/Program Files/Amazon/AWSCLIV2" ]] && PATH="$PATH:/c/Program Files/Amazon/AWSCLIV2"
say "Môi trường: $OS_KIND ($(uname -s))"
command -v curl >/dev/null 2>&1 || { warn "Cần curl (Git Bash có sẵn; Ubuntu: sudo apt install -y curl)."; exit 1; }
say "curl đã có ✓"
pause "Enter để tiếp tục"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Cài AWS CLI v2"
open_url "https://docs.aws.amazon.com/cli/latest/userguide/getting-started-install.html"
if command -v aws >/dev/null 2>&1; then
  say "Đã có: $(aws --version 2>&1)"
  note "Bỏ qua phần cài. Nếu dòng trên là aws-cli/1.x thì nên gỡ bản 1 và chạy lại wizard."
elif [[ "$OS_KIND" == windows ]]; then
  say "Chưa có AWS CLI. Trên Windows, cài một trong hai cách (cần quyền admin):"
  step "winget install -e --id Amazon.AWSCLI"
  step "hoặc theo tài liệu AWS: msiexec.exe /i https://awscli.amazonaws.com/AWSCLIV2.msi"
  pause "Cài xong thì Enter"
  [[ -d "/c/Program Files/Amazon/AWSCLIV2" ]] && PATH="$PATH:/c/Program Files/Amazon/AWSCLIV2"
  command -v aws >/dev/null 2>&1 || { warn "Vẫn chưa thấy aws. Mở lại Git Bash rồi chạy lại wizard."; exit 1; }
  say "Đã có: $(aws --version 2>&1)"
else
  command -v unzip >/dev/null 2>&1 || { confirm "Bộ cài cần unzip. Cài bằng sudo apt install -y unzip?" && sudo apt update && sudo apt install -y unzip; }
  say "Sẽ chạy đúng các lệnh trong tài liệu AWS (Linux x86_64), cần mật khẩu sudo:"
  note "  curl awscli-exe-linux-x86_64.zip → unzip → sudo ./aws/install"
  confirm "Cài AWS CLI v2 bây giờ?" || { warn "Chưa cài AWS CLI, dừng."; exit 1; }
  tmp=$(mktemp -d)
  curl -fsSL "https://awscli.amazonaws.com/awscli-exe-linux-x86_64.zip" -o "$tmp/awscliv2.zip"
  unzip -q "$tmp/awscliv2.zip" -d "$tmp"
  sudo "$tmp/aws/install"
  rm -rf "$tmp"
  say "Đã cài: $(aws --version 2>&1)"
fi
pause "Enter để tiếp tục"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "IAM user + access key cho CLI"
say "Tạo một IAM user riêng chỉ để deploy, không dùng tài khoản root cho CLI."
open_url "https://console.aws.amazon.com/iam/home#/users"
step "Đăng nhập AWS Console (root hoặc user có quyền quản trị IAM)."
step "IAM → Users → Create user. Tên: kafka-portal-deployer. KHÔNG cần bật console access."
step "Set permissions → Attach policies directly → tick AmazonS3FullAccess → Next → Create user."
step "Mở user vừa tạo → tab Security credentials → Access keys → Create access key."
step "Use case: Command Line Interface (CLI) → tick xác nhận → Next → Create access key."
step "Giữ trang 'Retrieve access keys' mở: secret chỉ hiện MỘT lần ở đây."
note "Tên nút trên console có thể khác đôi chút theo thời điểm; ý chính: user chỉ có quyền S3 + một access key."
pause "Đã thấy Access key ID và Secret access key? Enter để nhập"
note "Hai giá trị này chỉ được ghi vào file credentials của AWS CLI (~/.aws, trên Windows là %USERPROFILE%\.aws),"
note "không ghi vào repo hay deploy/s3.env."
set_aws_keys() {
  local AWS_KEY_ID="" AWS_KEY_SECRET=""
  ask AWS_KEY_ID "Access key ID (bắt đầu AKIA...):"
  ask_secret AWS_KEY_SECRET "Secret access key (ẩn khi gõ):"
  aws configure set aws_access_key_id "$AWS_KEY_ID" --profile "$S3_PROFILE"
  aws configure set aws_secret_access_key "$AWS_KEY_SECRET" --profile "$S3_PROFILE"
  aws configure set region ap-southeast-1 --profile "$S3_PROFILE"
  aws configure set output json --profile "$S3_PROFILE"
}
if aws sts get-caller-identity --profile "$S3_PROFILE" >/dev/null 2>&1 && ! confirm "Profile $S3_PROFILE đã có credential dùng được. Nhập key mới?"; then
  :
else
  set_aws_keys
fi
until ident=$(aws sts get-caller-identity --profile "$S3_PROFILE" --query Arn --output text 2>&1); do
  warn "Credential chưa dùng được: $ident"
  confirm "Nhập lại access key?" || { warn "Dừng: cần credential hợp lệ."; exit 1; }
  set_aws_keys
done
say "Đang đăng nhập với: $ident ✓"
write_env S3_PROFILE "$S3_PROFILE"
pause "Enter để tiếp tục"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Tạo bucket"
ask S3_REGION "Region (Enter = ap-southeast-1):" || true
S3_REGION="${S3_REGION:-ap-southeast-1}"
suggest="kafka-study-portal-$(od -An -N3 -tx1 /dev/urandom | tr -d ' \n')"   # 6 ký tự hex; không dùng head (SIGPIPE + pipefail)
say "Tên bucket là duy nhất trên toàn AWS: chữ thường, số, dấu '-', 3-63 ký tự."
while true; do
  ask S3_BUCKET "Tên bucket (Enter = $suggest):" || true
  S3_BUCKET="${S3_BUCKET:-$suggest}"
  if [[ ! "$S3_BUCKET" =~ ^[a-z0-9][a-z0-9-]{1,61}[a-z0-9]$ ]]; then
    warn "Tên không hợp lệ: $S3_BUCKET"; S3_BUCKET=""; continue
  fi
  if aws s3api head-bucket --bucket "$S3_BUCKET" --profile "$S3_PROFILE" >/dev/null 2>&1; then
    say "Bucket $S3_BUCKET đã có và bạn truy cập được: dùng lại ✓"; break
  fi
  if out=$(aws s3api create-bucket --bucket "$S3_BUCKET" --region "$S3_REGION" --profile "$S3_PROFILE" \
        $( [[ "$S3_REGION" == "us-east-1" ]] || printf -- '--create-bucket-configuration LocationConstraint=%s' "$S3_REGION" ) 2>&1); then
    say "Đã tạo s3://$S3_BUCKET ở $S3_REGION ✓"; break
  fi
  warn "Không tạo được: $out"
  note "Thường do tên đã có người dùng (BucketAlreadyExists). Chọn tên khác."
  S3_BUCKET=""
done
write_env S3_REGION "$S3_REGION"
write_env S3_BUCKET "$S3_BUCKET"
pause "Enter để tiếp tục"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Mở quyền đọc công khai cho bucket"
open_url "https://docs.aws.amazon.com/AmazonS3/latest/userguide/WebsiteAccessPermissionsReqd.html"
warn "Sau bước này AI CŨNG ĐỌC ĐƯỢC mọi file trong s3://$S3_BUCKET. Chỉ để nội dung công khai trong bucket này."
say "Sẽ làm hai việc (theo tài liệu AWS):"
step "Block Public Access của bucket: cho phép bucket policy public (vẫn chặn ACL public)."
step "Bucket policy PublicReadGetObject: mọi người được s3:GetObject trên s3://$S3_BUCKET/*."
confirm "Mở public bucket $S3_BUCKET?" || { warn "Dừng: website S3 chỉ phục vụ được nội dung public."; exit 1; }

account=$(aws sts get-caller-identity --profile "$S3_PROFILE" --query Account --output text)
acct=$(aws s3control get-public-access-block --account-id "$account" --profile "$S3_PROFILE" --region "$S3_REGION" \
        --query 'PublicAccessBlockConfiguration.[BlockPublicPolicy,RestrictPublicBuckets]' --output text 2>/dev/null || echo "none")
if [[ "$acct" == *True* ]]; then
  warn "Tài khoản đang bật Block Public Access ở cấp TÀI KHOẢN (BlockPublicPolicy/RestrictPublicBuckets = $acct)."
  note "S3 áp dụng tổ hợp chặt nhất giữa cấp tài khoản và cấp bucket, nên bucket sẽ vẫn bị chặn."
  note "Nới cấp tài khoản ảnh hưởng MỌI bucket: chúng chỉ public khi chính bucket đó cũng nới và có policy public."
  if confirm "Nới BlockPublicPolicy và RestrictPublicBuckets ở cấp tài khoản (giữ chặn ACL)?"; then
    aws s3control put-public-access-block --account-id "$account" --profile "$S3_PROFILE" --region "$S3_REGION" \
      --public-access-block-configuration BlockPublicAcls=true,IgnorePublicAcls=true,BlockPublicPolicy=false,RestrictPublicBuckets=false
    say "Đã nới cấp tài khoản ✓"
  else
    SKIPPED+=("Nới Block Public Access cấp tài khoản (S3 console → Block Public Access settings for this account)")
    warn "Bỏ qua: website sẽ trả 403 cho tới khi bạn nới cấp tài khoản."
  fi
fi

aws s3api put-public-access-block --bucket "$S3_BUCKET" --profile "$S3_PROFILE" \
  --public-access-block-configuration BlockPublicAcls=true,IgnorePublicAcls=true,BlockPublicPolicy=false,RestrictPublicBuckets=false
policy='{"Version":"2012-10-17","Statement":[{"Sid":"PublicReadGetObject","Effect":"Allow","Principal":"*","Action":["s3:GetObject"],"Resource":["arn:aws:s3:::'"$S3_BUCKET"'/*"]}]}'
if out=$(aws s3api put-bucket-policy --bucket "$S3_BUCKET" --policy "$policy" --profile "$S3_PROFILE" 2>&1); then
  say "Đã gắn bucket policy public-read ✓"
else
  warn "Không gắn được policy: $out"
  SKIPPED+=("Gắn bucket policy public-read cho $S3_BUCKET (thường do Block Public Access cấp tài khoản)")
fi
pause "Enter để tiếp tục"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Bật static website hosting"
aws s3 website "s3://$S3_BUCKET/" --index-document index.html --error-document index.html --profile "$S3_PROFILE"
say "Index document: index.html (trang gốc chuyển sang portal/) ✓"
say "Endpoint: $(website_url "$S3_REGION" "$S3_BUCKET")"
note "Endpoint website của S3 chỉ có HTTP, không có HTTPS."
pause "Enter để tiếp tục"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Upload lần đầu"
if command -v python >/dev/null 2>&1 && command -v node >/dev/null 2>&1; then
  say "Build lại nội dung: html2md + build_portal"
  PYTHONIOENCODING=utf-8 python scripts/html2md.py >/dev/null && node scripts/build_portal.mjs
elif [[ ! -f portal/course.js ]]; then
  warn "Thiếu portal/course.js và không có python/node ở đây. Build trên Windows rồi Enter."
  pause "Build xong thì Enter"
fi
say "Chạy scripts/deploy-s3.sh (aws s3 sync, bỏ .git, .claude, dist, target...)."
bash scripts/deploy-s3.sh
url="$(website_url "$S3_REGION" "$S3_BUCKET")"
for path in "" "portal/" "portal/course.js"; do
  code=$(curl -s -o /dev/null -w '%{http_code}' "$url/$path" || echo "000")
  if [[ "$code" == "200" ]]; then say "$url/$path → $code ✓"; else warn "$url/$path → $code"; fi
done
open_url "$url/"
say "Lần sau, trong PowerShell ở gốc repo:  .\scripts\deploy-s3.ps1   (build + sync một lệnh)"

finish
}

run_wizard "$@"; exit
